"""Config directory revisions generated by the Python implementation.

Regenerate with python -m tests.guildbotics.test_config_repository_golden.
"""

import json
import tempfile
from pathlib import Path

from guildbotics.workspace.config_repository import (
    ConfigPathInvalidError,
    ConfigRepository,
)

GOLDEN = Path(__file__).resolve().parents[2] / "records/golden/config_repository.json"
CASES = [
    {
        "name": "component_order",
        "files": {
            "intelligences/members.yml": "a",
            "intelligences/members-a.yml": "b",
            "intelligences/members/x.yml": "c",
            "intelligences/members.x/a": "d",
            "intelligences/名/a": "日本語",
            "intelligences/.hidden": "hidden",
        },
        "dirs": ["intelligences", "missing", ".", "./intelligences", "intelligences/"],
    },
    *[
        {
            "name": name,
            "files": {"tree/a": "a", "tree/nested/b": "b"},
            "links": {"tree/link": target},
            "dirs": ["tree", "tree/link"],
        }
        for name, target in [
            ("inside_directory", "tree/nested"),
            ("outside_directory", "<outside>"),
            ("inside_file", "tree/a"),
            ("outside_file", "<outside>/file"),
            ("missing_inside", "missing"),
            ("missing_outside", "<outside>/missing"),
        ]
    ],
]


def answers(root: Path, case: dict) -> dict:
    """Build only synthetic inputs; let ConfigRepository supply every answer."""
    config = root / ".guildbotics/config"
    config.mkdir(parents=True)
    outside = root / "outside"
    outside.mkdir()
    (outside / "file").write_text("outside", encoding="utf-8")
    for name, text in case["files"].items():
        path = config / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    for name, target in case.get("links", {}).items():
        path = config / name
        destination = (
            (outside / target.removeprefix("<outside>").lstrip("/"))
            if target.startswith("<outside>")
            else config / target
        )
        path.symlink_to(destination, target_is_directory=destination.is_dir())
    repo = ConfigRepository(root)
    result = {}
    for directory in case["dirs"]:
        try:
            result[directory] = {"revisions": repo.tree_revisions(directory)}
        except ConfigPathInvalidError:
            result[directory] = {"error": "invalid_path"}
    return result


def test_config_directory_revisions_match_python(tmp_path, symlinks):
    fixture = json.loads(GOLDEN.read_text(encoding="utf-8"))
    for case in fixture:
        assert answers(tmp_path / case["name"], case) == case["expected"]


if __name__ == "__main__":
    with tempfile.TemporaryDirectory() as directory:
        records = [
            {**case, "expected": answers(Path(directory) / case["name"], case)}
            for case in CASES
        ]
    GOLDEN.write_text(
        json.dumps(records, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )
